/*
 * A118695  Semiprimes which are divisible by their digital root.
 * https://oeis.org/A118695
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   not stated
 * Range:     u8 n <= 32, u16 n <= 4480, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   factor_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* This sequence is generated by brute‑force search.  The nth term is the
   nth positive integer that is a semiprime and divisible by its digital
   root. */
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/factor_u64.h"

seq_t a(idx_t n)
{
    if (n == 0) return 0;                     /* undefined for n = 0 */

    /* ----------------------------------------------------------------
       Static cache of the sequence.
       ---------------------------------------------------------------- */
    static seq_t *terms   = NULL;   /* stored terms */
    static size_t   size   = 0;      /* number of stored terms   */
    static size_t   capacity = 0;    /* allocated capacity       */
    static uint64_t next = 2;        /* next integer to test    */

    if (!terms) {
        capacity = 64;
        terms = (seq_t *)malloc(capacity * sizeof(seq_t));
    }

    /* ----------------------------------------------------------------
       Generate terms until we have at least n of them.
       ---------------------------------------------------------------- */
    while (size < (size_t)n) {
        uint64_t cand = next++;

        /* ---- digital‑root test ------------------------------------- */
        uint64_t dr = cand % 9;
        if (dr == 0) dr = 9;                  /* digital root of multiples of 9 is 9 */
        if (cand % dr != 0) continue;         /* not divisible by its digital root */

        /* ---- semiprime test ---------------------------------------- */
        static uint64_t primes[64];
        static uint64_t exponents[64];
        size_t fac_cnt;
        factor_u64(cand, primes, exponents, &fac_cnt);

        int sum_exps = 0;
        for (size_t i = 0; i < fac_cnt; ++i) sum_exps += (int)exponents[i];
        if (sum_exps != 2) continue;          /* need exactly two prime factors */

        /* ---- store the term ---------------------------------------- */
        if (size == capacity) {
            capacity <<= 1;
            terms = (seq_t *)realloc(terms, capacity * sizeof(seq_t));
        }
        terms[size++] = (seq_t)cand;
    }

    return terms[n - 1];
}
